17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity already exists";
57	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
58	    private static final String ERROR_DUPLICATE_EMAIL = "An owner with the given email already exists";
59	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given last name and address already exists";
60	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city has reached its owner capacity";
61	    private static final String ERROR_DAILY_OWNER_LIMIT = "The daily owner registration limit has been reached";
62	
63	    /**
64	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
65	     * class.
66	     *
67	     * @param e     Object referring to the thrown exception.
68	     * @param status HTTP response status.
69	     * @param url URL request.
70	     */
71	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
72	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
73	        problemDetail.setType(URI.create(url.toString()));
74	        problemDetail.setTitle(e.getClass().getSimpleName());
75	        problemDetail.setDetail(detail);
76	        problemDetail.setProperty("timestamp", Instant.now());
77	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
78	        return problemDetail;
79	    }
80	
81	    /**
82	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
83	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
84	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
85	     * would catch it and report an authorization failure as a 500.
86	     *
87	     * @param e The {@link AccessDeniedException} to propagate
88	     * @throws AccessDeniedException always
89	     */
90	    @ExceptionHandler(AccessDeniedException.class)
91	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
92	        throw e;
93	    }
94	
95	    /**
96	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
97	     *
98	     * @param e The {@link Exception} to be handled
99	     * @param request {@link HttpServletRequest} object referring to the current request.
100	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
101	     */
102	    @ExceptionHandler(Exception.class)
103	    @ResponseBody
104	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
105	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
106	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
107	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
108	        return ResponseEntity.status(status).body(detail);
109	    }
110	
111	    /**
112	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
113	     * method returns a 404 Not Found status if an entity does not exist.
114	     *
115	     * @param e The {@link DataIntegrityViolationException} to be handled
116	     * @param request {@link HttpServletRequest} object referring to the current request.
117	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
118	     */
119	    @ExceptionHandler(DataIntegrityViolationException.class)
120	    @ResponseBody
121	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
122	        logger.warn("Data integrity violation at {} {}: {}",
123	            request.getMethod(),
124	            request.getRequestURI(),
125	            e.getMessage());
126	        logger.debug("Data integrity violation stacktrace", e);
127	        HttpStatus status = HttpStatus.NOT_FOUND;
128	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
129	        return ResponseEntity.status(status).body(detail);
130	    }
131	
132	    /**
133	     * Handles exception thrown by Bean Validation on controller methods parameters
134	     *
135	     * @param e The {@link MethodArgumentNotValidException} to be handled
136	     * @param request {@link HttpServletRequest} object referring to the current request.
137	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
138	     */
139	    @ExceptionHandler(MethodArgumentNotValidException.class)
140	    @ResponseBody
141	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
142	        HttpStatus status = HttpStatus.BAD_REQUEST;
143	        BindingErrorsResponse errors = new BindingErrorsResponse();
144	        BindingResult bindingResult = e.getBindingResult();
145	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
146	        if (bindingResult.hasErrors()) {
147	            errors.addAllErrors(bindingResult);
148	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
149	                .map(FieldError::getField)
150	                .distinct()
151	                .toList();
152	            detail.setProperty("errors", invalidFields);
153	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
154	                .map(fieldError -> {
155	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
156	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
157	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
158	                        fieldError.getField(),
159	                        defaultMessage,
160	                        rejectedValue);
161	                    return new ValidationMessageDto(message)
162	                        .putAdditionalProperty("field", fieldError.getField())
163	                        .putAdditionalProperty("rejectedValue", rejectedValue)
164	                        .putAdditionalProperty("defaultMessage", defaultMessage);
165	                })
166	                .toList();
167	            logger.debug("Validation error at {} {}: {}",
168	                request.getMethod(),
169	                request.getRequestURI(),
170	                bindingResult.getFieldErrors());
171	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
172	            return ResponseEntity.status(status).body(detail);
173	        }
174	        return ResponseEntity.status(status).body(detail);
175	    }
176	
177	    /**
178	     * Handles {@link RequiredFieldsMissingException} raised when a request is missing or blank in
179	     * one or more required fields. Returns a 400 Bad Request whose body's {@code errors} array
180	     * lists the name of each offending field.
181	     *
182	     * @param e The {@link RequiredFieldsMissingException} to be handled
183	     * @param request {@link HttpServletRequest} object referring to the current request.
184	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
185	     */
186	    @ExceptionHandler(RequiredFieldsMissingException.class)
187	    @ResponseBody
188	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
189	        HttpStatus status = HttpStatus.BAD_REQUEST;
190	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
191	        detail.setProperty("errors", e.getMissingFields());
192	        logger.debug("Missing required fields at {} {}: {}",
193	            request.getMethod(),
194	            request.getRequestURI(),
195	            e.getMissingFields());
196	        return ResponseEntity.status(status).body(detail);
197	    }
198	
199	    /**
200	     * Handles {@link InvalidFieldsException} raised when a request carries one or more fields
201	     * whose values are present but invalid. Returns a 400 Bad Request whose body's {@code errors}
202	     * array lists the name of each offending field.
203	     *
204	     * @param e The {@link InvalidFieldsException} to be handled
205	     * @param request {@link HttpServletRequest} object referring to the current request.
206	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
207	     */
208	    @ExceptionHandler(InvalidFieldsException.class)
209	    @ResponseBody
210	    public ResponseEntity<ProblemDetail> handleInvalidFieldsException(InvalidFieldsException e, HttpServletRequest request) {
211	        HttpStatus status = HttpStatus.BAD_REQUEST;
212	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
213	        detail.setProperty("errors", e.getInvalidFields());
214	        logger.debug("Invalid fields at {} {}: {}",
215	            request.getMethod(),
216	            request.getRequestURI(),
217	            e.getInvalidFields());
218	        return ResponseEntity.status(status).body(detail);
219	    }
220	
221	    /**
222	     * Handles {@link DuplicateOwnerIdentityException} raised when an owner is created whose derived
223	     * identity key ({@code normalizedTelephone|email|householdId}) is already used by another owner.
224	     * Returns a 409 Conflict whose body's {@code errors} array names the offending
225	     * {@code identityKey} field.
226	     *
227	     * @param e The {@link DuplicateOwnerIdentityException} to be handled
228	     * @param request {@link HttpServletRequest} object referring to the current request.
229	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
230	     */
231	    @ExceptionHandler(DuplicateOwnerIdentityException.class)
232	    @ResponseBody
233	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerIdentityException(DuplicateOwnerIdentityException e, HttpServletRequest request) {
234	        HttpStatus status = HttpStatus.CONFLICT;
235	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
236	        detail.setProperty("errors", List.of("identityKey"));
237	        logger.debug("Duplicate owner identity at {} {}: {}",
238	            request.getMethod(),
239	            request.getRequestURI(),
240	            e.getIdentityKey());
241	        return ResponseEntity.status(status).body(detail);
242	    }
243	
244	    /**
245	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner is created with a
246	     * normalized telephone that is already used by another owner. Returns a 409 Conflict whose
247	     * body's {@code errors} array names the offending {@code telephone} field.
248	     *
249	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
250	     * @param request {@link HttpServletRequest} object referring to the current request.
251	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
252	     */
253	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
254	    @ResponseBody
255	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
256	        HttpStatus status = HttpStatus.CONFLICT;
257	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
258	        detail.setProperty("errors", List.of("telephone"));
259	        logger.debug("Duplicate owner telephone at {} {}: {}",
260	            request.getMethod(),
261	            request.getRequestURI(),
262	            e.getTelephone());
263	        return ResponseEntity.status(status).body(detail);
264	    }
265	
266	    /**
267	     * Handles {@link DuplicateOwnerEmailException} raised when an owner is created with a
268	     * lower-cased email that is already used by another owner. Returns a 409 Conflict whose
269	     * body's {@code errors} array names the offending {@code email} field.
270	     *
271	     * @param e The {@link DuplicateOwnerEmailException} to be handled
272	     * @param request {@link HttpServletRequest} object referring to the current request.
273	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
274	     */
275	    @ExceptionHandler(DuplicateOwnerEmailException.class)
276	    @ResponseBody
277	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerEmailException(DuplicateOwnerEmailException e, HttpServletRequest request) {
278	        HttpStatus status = HttpStatus.CONFLICT;
279	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_EMAIL);
280	        detail.setProperty("errors", List.of("email"));
281	        logger.debug("Duplicate owner email at {} {}: {}",
282	            request.getMethod(),
283	            request.getRequestURI(),
284	            e.getEmail());
285	        return ResponseEntity.status(status).body(detail);
286	    }
287	
288	    /**
289	     * Handles {@link DuplicateOwnerHouseholdException} raised when an owner is created whose last
290	     * name and address already match another owner (a shared household) without the request opting
291	     * in via the {@code sharesHousehold} flag. Returns a 409 Conflict whose body's {@code errors}
292	     * array names the offending {@code lastName} and {@code address} fields.
293	     *
294	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
295	     * @param request {@link HttpServletRequest} object referring to the current request.
296	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
297	     */
298	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
299	    @ResponseBody
300	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
301	        HttpStatus status = HttpStatus.CONFLICT;
302	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
303	        detail.setProperty("errors", List.of("lastName", "address"));
304	        logger.debug("Duplicate owner household at {} {}: lastName={} address={}",
305	            request.getMethod(),
306	            request.getRequestURI(),
307	            e.getLastName(),
308	            e.getAddress());
309	        return ResponseEntity.status(status).body(detail);
310	    }
311	
312	    /**
313	     * Handles {@link CityAtCapacityException} raised when an owner is created in a city that
314	     * already contains the maximum permitted number of owners. Returns a 409 Conflict whose
315	     * body's {@code errors} array names the offending {@code city} field.
316	     *
317	     * @param e The {@link CityAtCapacityException} to be handled
318	     * @param request {@link HttpServletRequest} object referring to the current request.
319	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
320	     */
321	    @ExceptionHandler(CityAtCapacityException.class)
322	    @ResponseBody
323	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
324	        HttpStatus status = HttpStatus.CONFLICT;
325	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
326	        detail.setProperty("errors", List.of("city"));
327	        logger.debug("City at capacity at {} {}: city={}",
328	            request.getMethod(),
329	            request.getRequestURI(),
330	            e.getCity());
331	        return ResponseEntity.status(status).body(detail);
332	    }
333	
334	    /**
335	     * Handles {@link DailyOwnerLimitException} raised when an owner is created on a day that has
336	     * already reached the maximum permitted number of owner registrations. Returns a 429 Too Many
337	     * Requests, since the request exceeds the allowed rate of owner creations for the current day.
338	     *
339	     * @param e The {@link DailyOwnerLimitException} to be handled
340	     * @param request {@link HttpServletRequest} object referring to the current request.
341	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
342	     */
343	    @ExceptionHandler(DailyOwnerLimitException.class)
344	    @ResponseBody
345	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitException(DailyOwnerLimitException e, HttpServletRequest request) {
346	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
347	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_OWNER_LIMIT);
348	        logger.debug("Daily owner limit reached at {} {}: date={}",
349	            request.getMethod(),
350	            request.getRequestURI(),
351	            e.getDate());
352	        return ResponseEntity.status(status).body(detail);
353	    }
354	
355	}
